// TH16 v1.00a Extra final boss spell: Boss10 transition + BossCard10 attack.
// Source (transcribe/work/th16/th16_s7_b18/source.txt):
//   st07bs.ecl.txt Boss10:142-191, BossCard10:957-1020,
//   BossCard10_at:1022-1055, _at2:1057-1085, _at3:1087-1111,
//   _at4:1113-1137, _move:1139-1151.
//
// Source clock: Boss10 waits 180 frames before BossCard10; BossCard10 timerReset
// (line 967) is the zero of $TIME and of setInterrupt/spellEx(118, 9000).
// Card budget = 120 shell buffer + 180 pre-wait + 9000 card window + 4 startup.
const TH16_ARROWHEAD: int = 544; // source etSprite type 12
const TH16_BIG_BALL: int = 640;  // source etSprite type 18
const TH16_BALL: int = 416;      // source etSprite type 4

const TIME_LIMIT: int = 9304;
const OPENING_BUFFER: int = 120;
const CARD_FRAMES: int = 9000;   // setInterrupt(0,0,9000) / spellEx(118,9000)
const PHASE_FRAMES: int = 6600;  // BossCard10_at gate $TIME >= $B (B=6600)

// BossCard10_at: fixed-direction fan, 1 way x 3 layers, ARROWHEAD/4.
// Layer speeds 3/2.5/2 with etDist 24 minus the ANIM birth offset 4*speed.
// Gate: $LIFE <= A, $TIME >= B, or the 9000-frame interrupt. The source also
// leaves on $GI2 == 1; GI2 is only written by the (out-of-range) BossDead sub.
sub boss_at(hp_thr: int, t_max: int) {
    sh_reset(0);
    sh_sprite(0, TH16_ARROWHEAD, 4);
    sh_ring(0, 0);
    sh_count(0, 1, 1);            // layers fired one by one: per-layer birth distance
    var c: angle = -90deg;        // %C = -1.570796f
    loop {
        sh_angle(0, c, 0deg);     // etAngle(0, %C, 0.08726646f); N=1 ignores delta
        c = c - 1720bam;          // %C -= 0.164934f
        var ru: int = rand(65536);
        var u: fx = (ru - 32768) as fx / 32768;
        c = c + (((u * 18fx) as int) as angle); // %C += RANDF2*0.1deg
        sh_speed(0, 3fx, 0fx);     sh_dist(0, 12fx);    sh_fire(0);  // q=0 speed 3
        sh_speed(0, 2.5fx, 0fx);   sh_dist(0, 14fx);    sh_fire(0);  // q=1 speed 2.5
        sh_speed(0, 2fx, 0fx);     sh_dist(0, 16fx);    sh_fire(0);  // q=2 speed 2
        var e: int = 5;           // $E = 5: five gate checks / waits per wave
        while e > 0 {
            if self_int(0) >= t_max || self_int(0) >= CARD_FRAMES || $self_hp <= hp_thr {
                return;
            }
            wait(1);
            e = e - 1;
        }
    }
}

// BossCard10_at2 bullet EX: ANIM(a=1, visual) -> WAIT 120 -> STEP a=1,b=1,c=4
// (segment boundary sets the fixed target angle %A, restores speed 0.01)
// -> VELTIME a=60, r=3.0, angle preserved (s=-999999).
xformdef AT2_BURST(dir: angle) {
    wait(120);
    set_angle(dir);
    step_speed(3fx, 60);
}

// BossCard10_at2: aimed 16-way ring, BIG_BALL/2, initial speed 0.01, etDist 24.
async sub boss_at2() {
    sh_reset(0);
    sh_sprite(0, TH16_BIG_BALL, 2);
    sh_ring(0, 1);
    sh_count(0, 16, 1);
    sh_speed(0, 0.01fx, 0fx);
    sh_dist(0, 24fx);
    loop {
        var a: angle = aim_player(); // getAngle(%A, FINAL_X, FINAL_Y, PLAYER_X2, PLAYER_Y2)
        sh_xform(0, AT2_BURST(a));
        sh_angle(0, a, 0deg);
        sh_fire(0);
        if self_int(0) >= CARD_FRAMES { return; }
        wait(40);
    }
}

// BossCard10_at3 bullet EX: ANIM(a=1, visual) -> BRIGHT -> VELTIME a=60, r=1.0.
xformdef AT3_SLOW {
    step_speed(1fx, 60);
}

// BossCard10_at3: player-facing 32-way ring, BALL/2, initial speed 0.3, etDist 24.
async sub boss_at3() {
    sh_reset(0);
    sh_sprite(0, TH16_BALL, 2);
    sh_ring(0, 1);
    sh_count(0, 32, 1);
    sh_speed(0, 0.3fx, 0fx);
    sh_dist(0, 22.8fx);          // 24 - 4*0.3 (ANIM birth offset)
    sh_xform(0, AT3_SLOW);
    _ = rand(65536);             // source %A = %RANDRAD before the loop; value never read
    loop {
        sh_angle(0, aim_player(), 0deg); // etAngle(2, ANGLE_PLAYER, 0.017453292f)
        sh_fire(0);
        if self_int(0) >= CARD_FRAMES { return; }
        wait(60);
    }
}

// BossCard10_at4: fixed-direction fan, 1 way x 4 layers, ARROWHEAD/2.
// Layer speeds 3/2.667/2.333/2; etDist 24 minus the ANIM birth offset.
async sub boss_at4() {
    sh_reset(0);
    sh_sprite(0, TH16_ARROWHEAD, 2);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    var c: angle = -90deg;       // %A = -1.570796f
    loop {
        sh_angle(0, c, 0deg);    // etAngle(3, %A, 0.08726646f); N=1 ignores delta
        c = c - 2813bam;         // %A -= 0.269653f
        var ru: int = rand(65536);
        var u: fx = (ru - 32768) as fx / 32768;
        c = c + (((u * 18fx) as int) as angle); // %A += RANDF2*0.1deg
        sh_speed(0, 3fx, 0fx);     sh_dist(0, 12fx);    sh_fire(0);
        sh_speed(0, 2.667fx, 0fx); sh_dist(0, 13.333fx); sh_fire(0);
        sh_speed(0, 2.333fx, 0fx); sh_dist(0, 14.667fx); sh_fire(0);
        sh_speed(0, 2fx, 0fx);     sh_dist(0, 16fx);    sh_fire(0);
        if self_int(0) >= CARD_FRAMES { return; }
        wait(7);
    }
}

// BossCard10_move: movePos(0,32); moveReset(); moveEllipse(pi/2, 0, 192, 0, 0, 0.83);
// moveEllipseTime(400, 0, 0.008726646, ...). Centre C=(0,32), theta0=pi/2,
// omega ramps 0 -> 0.5deg/frame over 400 frames, ratio 0.83 on the x axis.
async sub boss_move() {
    move_to(0, 0fx, 32fx, EASE_LINEAR);
    var acc: fx = 0fx;           // accumulated BAM
    var k: int = 0;
    loop {
        if k < 400 { k = k + 1; }
        acc = acc + (k as fx * 0.2275fx);   // 91bam/frame * k/400
        var th: angle = 90deg + ((acc as int) as angle);
        var px: fx = 159.36fx * cos(th);    // 0.83 * 192 * cos(theta)
        var py: fx = 32fx + 192fx * sin(th);
        move_to(0, px, py, EASE_LINEAR);
        wait(1);
    }
}

// Shared $TIME clock for the card, zeroed at BossCard10's timerReset.
async sub card_clock() {
    loop {
        set_self_int(0, self_int(0) + 1);
        wait(1);
    }
}

async sub boss_card() {
    set_invuln(65535);
    set_hitbox(24fx);            // Boss(): setHitbox(48,48) -> r=24
    set_hurtbox(20fx);           // Boss(): setHurtbox(40,40) -> r=20
    set_enemy_flag(ENEMY_NO_BODY, 0);     // Boss10 flagClear(3): body contact on
    move_to(0, 0fx, 416fx, EASE_LINEAR);  // Boss10 movePos(0,416) + zeroed velocity
    wait(180);                            // Boss10 line 188
    // ---- BossCard10 entry: timerReset (967), etClear(640) ----
    set_self_int(0, 0);
    spawn card_clock();
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(90);                             // +90 label at 995
    spawn boss_move();                    // @BossCard10_move() async
    boss_at(4000, PHASE_FRAMES);          // @BossCard10_at(4000, 6600)
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    spawn boss_at2();                     // @BossCard10_at2() async
    boss_at(2500, PHASE_FRAMES);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    spawn boss_at3();                     // @BossCard10_at3() async
    boss_at(1000, PHASE_FRAMES);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    spawn boss_at4();                     // @BossCard10_at4() async
    boss_at(0, 24000);                    // @BossCard10_at(0, 24000)
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 416fx, 5500, 0, 0, 0, boss_card);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
